import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.Pattern;
import org.json.JSONObject;

public class ReportServlet extends HttpServlet {

    private static final Pattern SAFE_IDENTIFIER = Pattern.compile("^[a-zA-Z_][a-zA-Z0-9_]*$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String sortCol = req.getParameter("sort");
        String filterExpr = req.getParameter("filter");

        if (reportType == null || dateRange == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate report type against whitelist
        if (!reportType.matches("^(sales|inventory|returns|audit)$")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate sort column - looks safe but sortCol isn't used here
        if (sortCol != null && !SAFE_IDENTIFIER.matcher(sortCol).matches()) {
            resp.sendError(400, "Invalid sort column");
            return;
        }

        // Build the query - dateRange is validated client-side only
        // filterExpr allows "advanced" filtering syntax
        String query = buildReportQuery(reportType, dateRange, filterExpr, sortCol);

        try {
            Connection conn = getConnection();
            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query);

            JSONObject result = new JSONObject();
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();

            StringBuilder csv = new StringBuilder();
            for (int i = 1; i <= cols; i++) {
                if (i > 1) csv.append(",");
                csv.append(meta.getColumnName(i));
            }
            csv.append("\n");

            while (rs.next()) {
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) csv.append(",");
                    csv.append(rs.getString(i));
                }
                csv.append("\n");
            }

            resp.setContentType("text/csv");
            resp.getWriter().write(csv.toString());

            rs.close();
            stmt.close();
            conn.close();
        } catch (SQLException e) {
            resp.sendError(500, "Query execution failed: " + e.getMessage());
        }
    }

    private String buildReportQuery(String type, String range, String filter, String sort) {
        StringBuilder sb = new StringBuilder();
        sb.append("SELECT * FROM report_").append(type);
        sb.append(" WHERE created_at >= '").append(range).append("'");

        if (filter != null && !filter.isEmpty()) {
            // Advanced filter expression - passed directly for flexibility
            sb.append(" AND (").append(filter).append(")");
        }

        if (sort != null) {
            sb.append(" ORDER BY ").append(sort);
        }

        return sb.toString();
    }

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getProperty("db.url"),
            System.getProperty("db.user"),
            System.getProperty("db.password")
        );
    }
}
